
const rows=[{"name":"asstFloatA","group":"Assistant / full view","file":"styles/views/assistant-view.css","animation":"asstFloatA 14s ease-in-out infinite","css":"@keyframes asstFloatA {\n    0%,100% { transform: translate(0,0) scale(1); }\n    50%     { transform: translate(-30px, 40px) scale(1.08); }\n}"},{"name":"asstFloatB","group":"Assistant / full view","file":"styles/views/assistant-view.css","animation":"asstFloatB 18s ease-in-out infinite","css":"@keyframes asstFloatB {\n    0%,100% { transform: translate(0,0) scale(1); }\n    50%     { transform: translate(40px, -30px) scale(1.1); }\n}"},{"name":"asstThinkingPulse","group":"Assistant / full view","file":"styles/views/assistant-view.css","animation":"asstThinkingPulse 1.4s ease-in-out infinite","css":"@keyframes asstThinkingPulse { 0%,100% { opacity: 0.6; } 50% { opacity: 1; } }"},{"name":"asstThinkingSpin","group":"Assistant / full view","file":"styles/views/assistant-view.css","animation":"asstThinkingSpin 2.6s linear infinite, asstThinkingPulse 1.4s ease-in-out infinite","css":"@keyframes asstThinkingSpin { to { transform: rotate(360deg); } }"},{"name":"asstThinkingSheen","group":"Assistant / full view","file":"styles/views/assistant-view.css","animation":"asstThinkingSheen 1.9s ease-in-out infinite","css":"@keyframes asstThinkingSheen { 0% { transform: translateX(-120%); } 60%,100% { transform: translateX(120%); } }"},{"name":"asstThinkingShimmer","group":"Assistant / full view","file":"styles/views/assistant-view.css","animation":"asstThinkingShimmer 2.2s linear infinite","css":"@keyframes asstThinkingShimmer { 0% { background-position: 200% 0; } 100% { background-position: -200% 0; } }"},{"name":"asstThinkingDot","group":"Assistant / full view","file":"styles/views/assistant-view.css","animation":"asstThinkingDot 1.2s ease-in-out infinite","css":"@keyframes asstThinkingDot { 0%,100% { opacity: 0.3; transform: translateY(0); } 50% { opacity: 1; transform: translateY(-2px); } }"},{"name":"asstMicPulse","group":"Assistant / full view","file":"styles/views/assistant-view.css","animation":"asstMicPulse 1.3s ease-in-out infinite","css":"@keyframes asstMicPulse {\n    0%, 100% { box-shadow: 0 0 0 0 rgba(224,72,61,0.55); }\n    50% { box-shadow: 0 0 0 6px rgba(224,72,61,0); }\n}"},{"name":"asstFade","group":"Assistant / full view","file":"styles/views/assistant-view.css","animation":"asstFade .5s ease","css":"@keyframes asstFade { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: none; } }"},{"name":"asstSpin","group":"Assistant / full view","file":"styles/views/assistant-view.css","animation":"asstSpin 0.8s linear infinite","css":"@keyframes asstSpin { to { transform: rotate(360deg); } }"},{"name":"asstCaretBlink","group":"Assistant / full view","file":"styles/views/assistant-view.css","animation":"asstCaretBlink 1s steps(2) infinite","css":"@keyframes asstCaretBlink { 0%,100% { opacity: 1; } 50% { opacity: 0; } }"},{"name":"chatbotThinkingPulse","group":"Assistant / floating panel","file":"styles/legacy/workspace-overrides.css","animation":"chatbotThinkingPulse 1.4s ease-in-out infinite","css":"@keyframes chatbotThinkingPulse { 0%,100% { opacity: 0.6; } 50% { opacity: 1; } }"},{"name":"chatbotThinkingSpin","group":"Assistant / floating panel","file":"styles/legacy/workspace-overrides.css","animation":"chatbotThinkingSpin 2.6s linear infinite, chatbotThinkingPulse 1.4s ease-in-out infinite","css":"@keyframes chatbotThinkingSpin { to { transform: rotate(360deg); } }"},{"name":"chatbotThinkingSheen","group":"Assistant / floating panel","file":"styles/legacy/workspace-overrides.css","animation":"chatbotThinkingSheen 1.9s ease-in-out infinite","css":"@keyframes chatbotThinkingSheen { 0% { transform: translateX(-120%); } 60%,100% { transform: translateX(120%); } }"},{"name":"chatbotThinkingShimmer","group":"Assistant / floating panel","file":"styles/legacy/workspace-overrides.css","animation":"chatbotThinkingShimmer 2.2s linear infinite","css":"@keyframes chatbotThinkingShimmer { 0% { background-position: 200% 0; } 100% { background-position: -200% 0; } }"},{"name":"chatbotThinkingDot","group":"Assistant / floating panel","file":"styles/legacy/workspace-overrides.css","animation":"chatbotThinkingDot 1.2s ease-in-out infinite","css":"@keyframes chatbotThinkingDot { 0%,100% { opacity: 0.3; transform: translateY(0); } 50% { opacity: 1; transform: translateY(-2px); } }"},{"name":"chatbotCaretBlink","group":"Assistant / floating panel","file":"styles/legacy/workspace-overrides.css","animation":"chatbotCaretBlink 1.05s steps(1, end) infinite","css":"@keyframes chatbotCaretBlink { 0%,49% { opacity: 1; } 50%,100% { opacity: 0; } }"},{"name":"chatbotMsgIn","group":"Assistant / floating panel","file":"styles/legacy/workspace-overrides.css","animation":"chatbotMsgIn 0.26s cubic-bezier(0.22, 0.61, 0.36, 1) both","css":"@keyframes chatbotMsgIn { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: none; } }"},{"name":"sutraMicPulse","group":"Assistant / floating panel","file":"styles/legacy/workspace-overrides.css","animation":"sutraMicPulse 1.3s ease-in-out infinite","css":"@keyframes sutraMicPulse {\n            0%, 100% { box-shadow: 0 0 0 0 rgba(224,72,61,0.55); }\n            50% { box-shadow: 0 0 0 6px rgba(224,72,61,0); }\n        }"},{"name":"flow-popover-in","group":"Assistant / floating panel","file":"styles/legacy/workspace-overrides.css","animation":"flow-popover-in 0.16s ease-out","css":"@keyframes flow-popover-in {\n            from { opacity: 0; transform: translateY(-4px) scale(0.98); }\n            to   { opacity: 1; transform: none; }\n        }"},{"name":"chat-spin","group":"Assistant / floating panel","file":"styles/legacy/workspace-overrides.css","animation":"chat-spin .9s linear infinite","css":"@keyframes chat-spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }"},{"name":"atelierIconsReveal","group":"Shared UI motion","file":"styles/base/microinteractions.css","animation":"atelierIconsReveal 140ms cubic-bezier(0.22, 1, 0.36, 1) both","css":"@keyframes atelierIconsReveal {\n  from { opacity: 0; transform: translateX(5px); }\n  to   { opacity: 0.6; transform: translateX(0); }\n}"},{"name":"atelierBackdropIn","group":"Shared UI motion","file":"styles/base/microinteractions.css","animation":"atelierBackdropIn 180ms ease both","css":"@keyframes atelierBackdropIn {\n  from { opacity: 0; }\n  to   { opacity: 1; }\n}"},{"name":"atelierModalIn","group":"Shared UI motion","file":"styles/base/microinteractions.css","animation":"atelierModalIn 220ms cubic-bezier(0.22, 1, 0.36, 1) both","css":"@keyframes atelierModalIn {\n  from {\n    transform: scale(0.93) translateY(10px);\n    opacity: 0;\n  }\n  to {\n    transform: scale(1) translateY(0);\n    opacity: 1;\n  }\n}"},{"name":"atelierDropIn","group":"Shared UI motion","file":"styles/base/microinteractions.css","animation":"atelierDropIn 160ms cubic-bezier(0.22, 1, 0.36, 1) both","css":"@keyframes atelierDropIn {\n  from {\n    opacity: 0;\n    transform: translateY(-6px) scale(0.97);\n  }\n  to {\n    opacity: 1;\n    transform: translateY(0) scale(1);\n  }\n}"},{"name":"atelierDropInUp","group":"Shared UI motion","file":"styles/base/microinteractions.css","animation":"atelierDropInUp 160ms cubic-bezier(0.22, 1, 0.36, 1) both","css":"@keyframes atelierDropInUp {\n  from {\n    opacity: 0;\n    transform: translateY(6px) scale(0.97);\n  }\n  to {\n    opacity: 1;\n    transform: translateY(0) scale(1);\n  }\n}"},{"name":"atelierSavePulse","group":"Shared UI motion","file":"styles/base/microinteractions.css","animation":"atelierSavePulse 1.4s ease-in-out infinite","css":"@keyframes atelierSavePulse {\n  0%, 100% { opacity: 0.65; }\n  50%       { opacity: 1; }\n}"},{"name":"atelierSavedFlash","group":"Shared UI motion","file":"styles/base/microinteractions.css","animation":"atelierSavedFlash 320ms cubic-bezier(0.22, 1, 0.36, 1) both","css":"@keyframes atelierSavedFlash {\n  0%   { opacity: 0.6; transform: scale(0.97); }\n  50%  { opacity: 1;   transform: scale(1.02); }\n  100% { opacity: 1;   transform: scale(1); }\n}"},{"name":"atelierTabActivate","group":"Shared UI motion","file":"styles/base/microinteractions.css","animation":"atelierTabActivate 180ms cubic-bezier(0.22, 1, 0.36, 1) both","css":"@keyframes atelierTabActivate {\n  from { transform: scale(0.94); opacity: 0.6; }\n  to   { transform: scale(1);    opacity: 1;   }\n}"},{"name":"atelierPopIn","group":"Shared UI motion","file":"styles/base/microinteractions.css","animation":"atelierPopIn 160ms cubic-bezier(0.22, 1, 0.36, 1) both","css":"@keyframes atelierPopIn {\n  from {\n    opacity: 0;\n    transform: translateY(-4px) scale(0.97);\n  }\n  to {\n    opacity: 1;\n    transform: translateY(0) scale(1);\n  }\n}"},{"name":"atelierCheckPop","group":"Shared UI motion","file":"styles/base/microinteractions.css","animation":"atelierCheckPop 220ms cubic-bezier(0.22, 1, 0.36, 1) both","css":"@keyframes atelierCheckPop {\n  0%   { transform: scale(0.85); }\n  60%  { transform: scale(1.18); }\n  100% { transform: scale(1); }\n}"},{"name":"atelierEmptyFadeIn","group":"Shared UI motion","file":"styles/base/microinteractions.css","animation":"atelierEmptyFadeIn 280ms cubic-bezier(0.22, 1, 0.36, 1) both","css":"@keyframes atelierEmptyFadeIn {\n  from { opacity: 0; transform: translateY(4px); }\n  to   { opacity: 1; transform: translateY(0); }\n}"},{"name":"tooltip-fade","group":"Optional theme motion","file":"styles/themes/sutra-pro.css","animation":"tooltip-fade 0.15s ease both","css":"@keyframes tooltip-fade {\n    from { opacity: 0; transform: translateY(-4px); }\n    to { opacity: 1; transform: translateY(0); }\n}"},{"name":"panel-slide-in","group":"Optional theme motion","file":"styles/themes/sutra-pro.css","animation":"panel-slide-in 0.25s ease both","css":"@keyframes panel-slide-in {\n    from { opacity: 0; transform: translateX(20px); }\n    to { opacity: 1; transform: translateX(0); }\n}"},{"name":"comment-anchor-flash","group":"Optional theme motion","file":"styles/themes/sutra-pro.css","animation":"comment-anchor-flash 1.8s ease","css":"@keyframes comment-anchor-flash {\n    0%, 100% { background: transparent; }\n    20% { background: rgba(255, 213, 74, 0.5); }\n}"},{"name":"panel-slide-down","group":"Optional theme motion","file":"styles/themes/sutra-pro.css","animation":"panel-slide-down 0.2s ease both","css":"@keyframes panel-slide-down {\n    from { opacity: 0; transform: translateY(-10px); }\n    to { opacity: 1; transform: translateY(0); }\n}"},{"name":"panel-slide-in-left","group":"Optional theme motion","file":"styles/themes/sutra-pro.css","animation":"panel-slide-in-left 0.25s ease both","css":"@keyframes panel-slide-in-left {\n    from { opacity: 0; transform: translateX(-20px); }\n    to { opacity: 1; transform: translateX(0); }\n}"},{"name":"user-mode-pop","group":"Optional theme motion","file":"styles/themes/sutra-pro.css","animation":"user-mode-pop 0.4s cubic-bezier(0.22, 1, 0.36, 1) both","css":"@keyframes user-mode-pop {\n    from { transform: scale(0.92) translateY(10px); opacity: 0; }\n    to { transform: scale(1) translateY(0); opacity: 1; }\n}"},{"name":"notif-quote-fade-in","group":"Optional theme motion","file":"styles/themes/sutra-pro.css","animation":"notif-quote-fade-in 0.6s cubic-bezier(0.22, 1, 0.36, 1) both","css":"@keyframes notif-quote-fade-in {\n    from { opacity: 0; transform: translateY(4px); }\n    to   { opacity: 0.7; transform: translateY(0); }\n}"},{"name":"atelier-dialog-fade","group":"Optional theme motion","file":"styles/themes/sutra-pro.css","animation":"atelier-dialog-fade 0.18s ease both","css":"@keyframes atelier-dialog-fade {\n    from { opacity: 0; }\n    to { opacity: 1; }\n}"},{"name":"atelier-dialog-pop","group":"Optional theme motion","file":"styles/themes/sutra-pro.css","animation":"atelier-dialog-pop 0.25s cubic-bezier(0.22, 1, 0.36, 1) both","css":"@keyframes atelier-dialog-pop {\n    from { transform: scale(0.95) translateY(8px); opacity: 0; }\n    to { transform: scale(1) translateY(0); opacity: 1; }\n}"},{"name":"cram-pulse-border","group":"Optional theme motion","file":"styles/themes/sutra-pro.css","animation":"cram-pulse-border 2s ease-in-out infinite","css":"@keyframes cram-pulse-border {\n    0%, 100% { border-left-color: #c83838; }\n    50% { border-left-color: #ff5555; }\n}"},{"name":"cram-detail-in","group":"Optional theme motion","file":"styles/themes/sutra-pro.css","animation":"cram-detail-in 0.3s ease both","css":"@keyframes cram-detail-in {\n    from { opacity: 0; transform: translateY(8px); }\n    to { opacity: 1; transform: translateY(0); }\n}"},{"name":"testing-panel-fade","group":"Optional theme motion","file":"styles/themes/sutra-pro.css","animation":"testing-panel-fade 0.2s ease both","css":"@keyframes testing-panel-fade {\n    from { opacity: 0; transform: translateY(4px); }\n    to { opacity: 1; transform: translateY(0); }\n}"},{"name":"th2-pulse","group":"Optional theme motion","file":"styles/themes/sutra-pro.css","animation":"th2-pulse 1.4s ease-out 1","css":"@keyframes th2-pulse {\n    0% { transform: scale(1); }\n    40% { transform: scale(1.03); }\n    100% { transform: scale(1); }\n}"},{"name":"th2PanelFlash","group":"Optional theme motion","file":"styles/themes/sutra-pro.css","animation":"th2PanelFlash 1.2s ease","css":"@keyframes th2PanelFlash { 0% { box-shadow: 0 0 0 2px var(--accent); } 100% { box-shadow: none; } }"},{"name":"macosFloatIn","group":"Optional theme motion","file":"styles/themes/macos26-redesign.css","animation":"macosFloatIn 460ms cubic-bezier(0.2, 0.8, 0.2, 1) both","css":"@keyframes macosFloatIn {\n    from { opacity: 0; transform: translateY(10px) scale(0.990); }\n    to   { opacity: 1; transform: translateY(0)     scale(1);    }\n}"},{"name":"macosRiseIn","group":"Optional theme motion","file":"styles/themes/macos26-redesign.css","animation":"macosRiseIn 520ms cubic-bezier(0.22, 1, 0.36, 1) both","css":"@keyframes macosRiseIn {\n    from { opacity: 0; transform: translateY(7px); }\n    to   { opacity: 1; transform: translateY(0);   }\n}"},{"name":"identityDrift","group":"Optional theme motion","file":"styles/themes/macos26-redesign.css","animation":null,"css":"@keyframes identityDrift {\n    0% { transform: translate3d(-1%, -1%, 0) scale(1); }\n    50% { transform: translate3d(1.2%, 1.2%, 0) scale(1.02); }\n    100% { transform: translate3d(-0.6%, 0.8%, 0) scale(1.01); }\n}"}];let paused=false;const grid=document.getElementById('grid');
function applySpeed(){document.getAnimations().forEach(a=>{a.playbackRate=Number(document.getElementById('speed').value);if(paused)a.pause();else a.play()})}
function render(){grid.replaceChildren();const family=document.getElementById('group').value;const visible=rows.filter(r=>family==='All'||(family==='Assistant'?r.group.startsWith('Assistant'):r.group===family));document.getElementById('count').textContent=visible.length+' definitions';for(const row of visible){const card=document.createElement('article');card.className='card';const head=document.createElement('div');head.className='head';const label=document.createElement('div');const g=document.createElement('div');g.className='group';g.textContent=row.group;const h=document.createElement('h2');h.textContent=row.name;label.append(g,h);const replay=document.createElement('button');replay.className='replay';replay.textContent='Replay';head.append(label,replay);const stage=document.createElement('div');stage.className='stage';const sample=document.createElement('div');sample.className='sample';sample.textContent='Sutra Assistant';let targets=[sample];if(/Float/.test(row.name)){sample.classList.add('orb');sample.textContent=''}else if(/Spin|spin|Pulse/.test(row.name)){sample.classList.add('symbol');sample.textContent=/Mic/.test(row.name)?'◉':'✧'}else if(/Caret/.test(row.name)){const line=document.createElement('span');line.textContent='Here is your revised draft ';sample.classList.add('caret');stage.appendChild(line)}else if(/Shimmer/.test(row.name)){sample.classList.add('shimmer');sample.textContent='Thinking'}else if(/Sheen/.test(row.name)){const overlay=document.createElement('i');overlay.className='sheen';sample.append(overlay);targets=[overlay]}else if(/Dot/.test(row.name)){sample.textContent='Thinking ';targets=[];for(let n=0;n<3;n++){const dot=document.createElement('i');dot.className='dot';sample.append(dot);targets.push(dot)}}stage.append(sample);const foot=document.createElement('div');foot.className='foot';const timing=document.createElement('div');timing.className='meta';timing.textContent=row.animation||'Definition only — no active timing found in this source';const source=document.createElement('div');source.className='meta';source.textContent=row.file;const details=document.createElement('details');const summary=document.createElement('summary');summary.textContent='Exact CSS';const pre=document.createElement('pre');pre.textContent=row.css;details.append(summary,pre);foot.append(timing,source,details);card.append(head,stage,foot);grid.append(card);const play=()=>{targets.forEach((el,n)=>{el.style.animation='none';void el.offsetWidth;el.style.animation=row.animation||'none';if(/Dot/.test(row.name))el.style.animationDelay=(n*.18)+'s'});applySpeed()};replay.onclick=play;play()}}
document.getElementById('group').onchange=render;document.getElementById('replay').onclick=()=>grid.querySelectorAll('.replay').forEach(b=>b.click());document.getElementById('speed').onchange=applySpeed;document.getElementById('pause').onclick=e=>{paused=!paused;e.target.textContent=paused?'Resume':'Pause';applySpeed()};document.getElementById('reduce').onchange=e=>document.body.classList.toggle('reduce',e.target.checked);document.getElementById('theme').onclick=e=>{const light=document.body.classList.toggle('light');e.target.textContent=light?'Dark theme':'Light theme'};render();
